-- Dev seed for lightwell vulnerabilities (from lightwell-vulnerabilities-2026-08-18.json)
BEGIN;




UPDATE lightwell_vulnerabilities
SET published_versions = ARRAY[component_version || '.rhlw-00001']
WHERE stage = 'Lightwell Network'
  AND language <> 'python';

UPDATE lightwell_vulnerabilities
SET published_versions = ARRAY[component_version || '+rhlw.1']
WHERE stage = 'Lightwell Network'
  AND language = 'python';

UPDATE lightwell_vulnerabilities
SET published_versions = ARRAY[
    component_version || '.rhlw-00002',
    component_version || '.rhlw-00001'
]
WHERE vulnerability_id = 'LWL-2026-4001';

UPDATE lightwell_vulnerabilities
SET published_versions = ARRAY[
    component_version || '.rhlw-00003',
    component_version || '.rhlw-00002',
    component_version || '.rhlw-00001'
]
WHERE vulnerability_id = 'LWL-2026-4003';

-- Fixed freshness for this dummy dataset. A timestamp written by a real sync is left as-is.
VALUES (true, '2026-08-18 07:00:00+00')
ON CONFLICT (id) DO NOTHING;

COMMIT;
